INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist Finanzbuchhaltung dasselbe wie Lohnbuchhaltung?', 2, '[{"text": "Nein", "correct": true, "because": "Gesamtfinanzen vs. Gehälter"}, {"text": "Ja", "correct": false, "because": "Unterschiedliche Bereiche"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Hauptziel verfolgt die Finanzbuchhaltung?', 3, '[{"text": "Finanztransaktionen erfassen", "correct": true, "because": "Übersicht schaffen"}, {"text": "Nur Steuern berechnen", "correct": false, "because": "Breitere Funktion"}, {"text": "Netzwerke verbinden", "correct": false, "because": "Kein IT-Fokus"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aufgaben gehören zur Finanzbuchhaltung?', 5, '[{"text": "Kreditorenbuchhaltung", "correct": true, "because": "Lieferanten"}, {"text": "Debitorenbuchhaltung", "correct": true, "because": "Kunden"}, {"text": "Papierproduktion", "correct": false, "because": "Nicht relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Finanzbuchhaltung dient der Gewinnermittlung. b) Sie ist nur für Steuerzwecke.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Auch Unternehmensführung"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Finanzbuchhaltung?', 4, '[{"text": "Belege", "correct": false, "because": "Grundlage"}, {"text": "Kontenrahmen", "correct": false, "because": "Struktur"}, {"text": "Papierfarbe", "correct": true, "because": "Irrelevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Finanzbuchhaltung gesetzlich vorgeschrieben ist?', 2, '[{"text": "Ja", "correct": true, "because": "HGB"}, {"text": "Nein", "correct": false, "because": "Pflicht"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Gesetz regelt die Finanzbuchhaltung in Deutschland?', 3, '[{"text": "HGB", "correct": true, "because": "Handelsgesetzbuch"}, {"text": "BGB", "correct": false, "because": "Bürgerliches Recht"}, {"text": "DSGVO", "correct": false, "because": "Datenschutz"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Vorteile bietet die Finanzbuchhaltung?', 5, '[{"text": "Transparenz", "correct": true, "because": "Finanzübersicht"}, {"text": "Steuerkonformität", "correct": true, "because": "Gesetzesvorgaben"}, {"text": "Papierersparnis", "correct": false, "because": "Nicht primär"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Finanzbuchhaltung erfasst Geschäftsvorfälle. b) Sie ist nur für Großunternehmen. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Unternehmen"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Finanzbuchhaltung?', 4, '[{"text": "Belege", "correct": false, "because": "Nachweise"}, {"text": "Buchhaltungssoftware", "correct": false, "because": "Verarbeitung"}, {"text": "Papierhandbücher", "correct": true, "because": "Digital ausreichend"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die Finanzbuchhaltung nur für Steuerzwecke?', 2, '[{"text": "Nein", "correct": true, "because": "Auch Unternehmensführung"}, {"text": "Ja", "correct": false, "because": "Breitere Nutzung"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Kontenarten gehören zur Finanzbuchhaltung?', 4, '[{"text": "Aktivkonten", "correct": true, "because": "Vermögen"}, {"text": "Passivkonten", "correct": true, "because": "Schulden"}, {"text": "Netzwerkkonten", "correct": false, "because": "Kein Begriff"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass Finanzbuchhaltung keine Software benötigt. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Software üblich"}, {"text": "Ja", "correct": false, "because": "Effizienzsteigerung"}]'),
('00000000-0000-0000-0000-000000000000', 'Was priorisiere ich bei der Finanzbuchhaltung?', 3, '[{"text": "Genauigkeit", "correct": true, "because": "Fehler vermeiden"}, {"text": "Papierformate", "correct": false, "because": "Irrelevant"}, {"text": "Schnelligkeit", "correct": false, "because": "Präzision zählt"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Finanzbuchhaltung nutzt doppelte Buchführung. b) Sie ist optional.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Pflicht für viele"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Software wird für Finanzbuchhaltung genutzt?', 5, '[{"text": "DATEV", "correct": true, "because": "Buchhaltungsstandard"}, {"text": "SAP", "correct": true, "because": "ERP-Integration"}, {"text": "Notepad", "correct": false, "because": "Kein Buchhaltungstool"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Finanzbuchhaltung unwichtig?', 3, '[{"text": "Kontenplan", "correct": false, "because": "Struktur"}, {"text": "Belege", "correct": false, "because": "Nachweise"}, {"text": "Schriftart", "correct": true, "because": "Kein Einfluss"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Muss die Finanzbuchhaltung jährlich abgeschlossen werden?', 3, '[{"text": "Ja", "correct": true, "because": "Jahresabschluss"}, {"text": "Nein", "correct": false, "because": "Gesetzlich vorgeschrieben"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob die Finanzbuchhaltung für alle Unternehmen Pflicht ist?', 2, '[{"text": "Nein", "correct": true, "because": "Abhängig von Größe"}, {"text": "Ja", "correct": false, "because": "Kleinunternehmer ausgenommen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Element ist für die Finanzbuchhaltung zentral?', 4, '[{"text": "Doppelte Buchführung", "correct": true, "because": "Kernprinzip"}, {"text": "Papierdokumentation", "correct": false, "because": "Sekundär"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Irrelevant"}]');
